static long long programmable_down;
static int handle_programmable(int ui, int code, int val, long long now) {
    if (code != KEY_PROGRAMMABLE_RAW) return 0;
    if (val == 1) {
        programmable_down = now;
    } else if (val == 0 && programmable_down) {
        int out = now - programmable_down >= PROGRAMMABLE_LONG_NS ? KEY_MACRO2 : KEY_MACRO1;
        programmable_down = 0;
        emit_key(ui, out, 1);
        emit_key(ui, out, 0);
    }
    return 1;
}
